  // Source word indices of S1,S1,S2,S2,S3,S4,D1,D2,D3,D4 (index 16 = zero word).
  const uint8_t TERM[10][8] = {
    {16,16,16,11,12,13,14,15}, {16,16,16,11,12,13,14,15},
    {16,16,16,12,13,14,15,16}, {16,16,16,12,13,14,15,16},
    {8,9,10,16,16,16,14,15},   {9,10,11,13,14,15,13,8},
    {11,12,13,16,16,16,8,10},  {12,13,14,15,16,16,9,11},
    {13,14,15,8,9,10,16,12},   {14,15,16,9,10,11,16,13}};
