    uint32_t b = 0;
    for (int i = 0; i < 8; ++i) {
      uint64_t d = (uint64_t)R[i] - (uint64_t)P[i] - (uint64_t)b;
      D[i] = (uint32_t)d;
      b = (uint32_t)(d >> 63);
    }
    uint32_t doadd = t >> 31;
    uint32_t nz = (t != 0) ? 1u : 0u;
    uint32_t dosub = (1u - doadd) & (nz | (1u - b));
    uint32_t ma = 0u - doadd, ms = 0u - dosub;
    for (int i = 0; i < 8; ++i)
      R[i] = (A[i] & ma) | (D[i] & ms) | (R[i] & ~(ma | ms));
    t = t + ((uint32_t)ca & doadd) - (b & dosub);
